import {el,listen} from '../dom.js';
import {awaitAccountMutations} from '../mutation-lifetime.js';
import {setPreference} from '../preferences.js';
const ns='http://www.w3.org/2000/svg';
function icon(kind){const svg=document.createElementNS(ns,'svg');for(const [k,v] of Object.entries({viewBox:'0 0 24 24',fill:'none',stroke:'currentColor','stroke-width':'1.6','stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':'true',width:'1em',height:'1em',focusable:'false',class:'text-[18px]'}))svg.setAttribute(k,v);
 // Exact source geometry from src/components/ui/icons.tsx; visual parity unverified.
 const p=document.createElementNS(ns,'path');p.setAttribute('d',kind==='day'?'M12 2.5v2M12 19.5v2M2.5 12h2M19.5 12h2M5.2 5.2l1.4 1.4M17.4 17.4l1.4 1.4M18.8 5.2l-1.4 1.4M6.6 17.4l-1.4 1.4':'M20 14.5A8.5 8.5 0 0 1 9.5 4a8.5 8.5 0 1 0 10.5 10.5z');svg.append(p);if(kind==='day'){const c=document.createElementNS(ns,'circle');c.setAttribute('cx','12');c.setAttribute('cy','12');c.setAttribute('r','4');svg.append(c);}return svg;}
export function controls({dict,locale,signal,refresh,state}){
 let theme=document.documentElement.dataset.theme,themePending=false,localePending=false;const header=el('header',{'data-auth-controls':'',class:'absolute inset-x-0 top-0 flex flex-wrap items-center justify-end gap-3 p-4'});
 const group=el('div',{role:'group','aria-label':dict.theme.toggle,'data-theme-toggle':theme,class:'flex items-center gap-1'});const failure=el('span',{role:'alert',class:'text-xs text-band-bad'});const buttons=[];failure.hidden=true;
 const sync=()=>buttons.forEach((b,i)=>{const active=['day','night'][i]===theme;b.className=active?'theme-btn theme-btn-active':'theme-btn';b.setAttribute('aria-pressed',String(active));});
 for(const value of ['day','night']){const b=el('button',{type:'button','data-theme-option':value,'aria-label':dict.theme[value],title:dict.theme[value]},icon(value));buttons.push(b);listen(b,'click',async()=>{if(signal.aborted||themePending||theme===value)return;themePending=true;const previous=theme;theme=value;document.documentElement.dataset.theme=theme;group.dataset.themeToggle=theme;sync();buttons.forEach(b=>b.disabled=true);failure.textContent='';failure.hidden=true;group.setAttribute('aria-busy','true');try{await setPreference('theme',value,signal);}catch{if(signal.aborted)return;theme=previous;document.documentElement.dataset.theme=theme;group.dataset.themeToggle=theme;sync();failure.textContent=dict.common.error;failure.hidden=false;}finally{themePending=false;buttons.forEach(b=>b.disabled=false);group.removeAttribute('aria-busy');}},signal);group.append(b);}sync();group.prepend(failure);
 const locales=el('div',{'data-locale-switcher':'',class:'flex flex-col items-start gap-1'});const lg=el('div',{role:'group','aria-label':dict.locale.switchLabel,class:'flex overflow-hidden rounded-sm border border-ink-100 text-xs font-medium'});const err=el('span',{role:'alert',class:'text-xs text-band-bad'});
 err.hidden=true;const localeStatus=el('span',{role:'status',class:'sr-only'},dict.loadingPage.label);
 for(const code of ['uz','en']){const b=el('button',{type:'button',lang:code,'aria-label':dict.locale[code],'aria-pressed':String(code===locale),class:'px-2.5 py-1 uppercase '+(code===locale?'bg-signal-600 text-signal-contrast':'bg-paper-raised text-ink-500 hover:bg-paper-sunken')},code);listen(b,'click',async()=>{if(signal.aborted||localePending||code===locale)return;localePending=true;const bs=[...lg.querySelectorAll('button')];bs.forEach(b=>b.disabled=true);err.textContent='';err.hidden=true;locales.append(localeStatus);lg.setAttribute('aria-busy','true');try{await setPreference('locale',code,signal);await awaitAccountMutations(state,signal);if(!signal.aborted){document.documentElement.lang=code;await refresh();}}catch{if(!signal.aborted){err.textContent=dict.auth.errorNetwork;err.hidden=false;}}finally{localePending=false;localeStatus.remove();bs.forEach(b=>b.disabled=false);lg.removeAttribute('aria-busy');}},signal);lg.append(b);}locales.append(lg,err);header.append(group,locales);return header;
}
